    public static void Apply(IDictionary<string, Dictionary<string, string>> dictionaries)
    {
        for (var languageIndex = 0; languageIndex < Languages.Length; languageIndex++)
        {
            if (!dictionaries.TryGetValue(Languages[languageIndex], out var dictionary))
                dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            foreach (var row in Rows)
            {
                var parts = row.Split('|');
                if (parts.Length <= languageIndex + 1)
                    continue;

                dictionary[parts[0]] = parts[languageIndex + 1];
            }

            dictionaries[Languages[languageIndex]] = dictionary;
        }
    }
}
